parameters.new_string:
        "script": "var fields = ($vars.extractInvoice.output && $vars.extractInvoice.output.ExtractionResult && $vars.extractInvoice.output.ExtractionResult.ResultsDocument && $vars.extractInvoice.output.ExtractionResult.ResultsDocument.Fields) ? $vars.extractInvoice.output.ExtractionResult.ResultsDocument.Fields : [];
var normalized = fields.map(function(f) {
  return { Id: f.FieldId, Name: f.FieldName, Value: (f.Values && f.Values.length > 0) ? f.Values[0] : null, Type: f.FieldType, IsMissing: f.IsMissing, Confidence: f.Confidence };
});
var invField = null;
for (var i = 0; i < normalized.length; i++) {
  var fn = (normalized[i].Name || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  if (fn === 'invoicenumber' || fn === 'invoiceno' || fn === 'invoice') { invField = normalized[i]; break; }
}
var rawNum = invField && invField.Value ? (invField.Value.Value !== undefined ? String(invField.Value.Value) : String(invField.Value)) : '';
var invoiceNumber = rawNum.trim().toUpperCase();
if (invoiceNumber && invoiceNumber.indexOf('MCS-') !== 0) { invoiceNumber = 'MCS-' + invoiceNumber; }
return { fields: normalized, invoiceNumber: invoiceNumber };"

